/* From Uiverse.io by joe-watson-sbf  - Tags: glassmorphism, animation, card, hover, card template, cardhover , card animation, card hover */
.__UIV_SCOPE__ .container {
  color: white;
  position: relative;
  font-family: sans-serif;
}

.__UIV_SCOPE__ .container::before,
.__UIV_SCOPE__ .container::after {
  content: "";
  background-color: #fab5704c;
  position: absolute;
}

.__UIV_SCOPE__ .container::before {
  border-radius: 50%;
  width: 6rem;
  height: 6rem;
  top: 30%;
  right: 7%;
}

.__UIV_SCOPE__ .container::after {
  content: "";
  position: absolute;
  height: 3rem;
  top: 8%;
  right: 5%;
  border: 1px solid;
}

.__UIV_SCOPE__ .container .box {
  width: 11.875em;
  height: 15.875em;
  padding: 1rem;
  background-color: rgba(255, 255, 255, 0.074);
  border: 1px solid rgba(255, 255, 255, 0.222);
  -webkit-backdrop-filter: blur(20px);
  backdrop-filter: blur(20px);
  border-radius: 0.7rem;
  transition: all ease 0.3s;
}

.__UIV_SCOPE__ .container .box {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.__UIV_SCOPE__ .container .box .title {
  font-size: 2rem;
  font-weight: 500;
  letter-spacing: 0.1em;
}

.__UIV_SCOPE__ .container .box div strong {
  display: block;
  margin-bottom: 0.5rem;
}

.__UIV_SCOPE__ .container .box div p {
  margin: 0;
  font-size: 0.9em;
  font-weight: 300;
  letter-spacing: 0.1em;
}

.__UIV_SCOPE__ .container .box div span {
  font-size: 0.7rem;
  font-weight: 300;
}

.__UIV_SCOPE__ .container .box div span:nth-child(3) {
  font-weight: 500;
  margin-right: 0.2rem;
}

.__UIV_SCOPE__ .container .box:hover {
  box-shadow: 0px 0px 20px 1px #ffbb763f;
  border: 1px solid rgba(255, 255, 255, 0.454);
}
